c=1.8;phi=.88;mu=15.;sig=9.;x0=45.;h=np.arange(0,31);f=mu+phi**h*(x0-mu);sd=np.sqrt(sig**2*(1-phi**(2*h))/(1-phi**2));ax.plot(h,f,color=ACCENT,lw=2,label='forecast mean');ax.plot(h,mu+2*sd,color=WARM,ls='--',label='+2 forecast-error standard deviation');ax.plot(h,mu-2*sd,color=WARM,ls='--');ax.axhline(mu,color=GOOD,ls=':',label='long-run mean');ax.set_xlabel('horizon (trading days)');ax.set_ylabel('spread (bp)');ax.set_title('Mean reversion narrows the point forecast, not the future risk',loc='left');ax.legend(fontsize=7)
